begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();
select ok(not has_function_privilege('anon','public.collection_snapshot()','execute'),'snapshot unavailable anonymously');
select ok(not has_function_privilege('anon','public.save_collection_copy(uuid,uuid,uuid,text)','execute'),'copy RPC unavailable anonymously');
select ok(not has_function_privilege('anon','public.save_movie_diary(uuid,boolean,smallint)','execute'),'diary RPC unavailable anonymously');
select ok(not has_function_privilege('anon','public.set_default_library(uuid)','execute'),'default RPC unavailable anonymously');
select ok(not has_function_privilege('anon','public.create_collection_library(uuid,text)','execute'),'library RPC unavailable anonymously');
select ok(not (select prosecdef from pg_proc where oid='public.collection_snapshot()'::regprocedure),'snapshot uses caller RLS');
select ok(not (select prosecdef from pg_proc where oid='public.save_collection_copy(uuid,uuid,uuid,text)'::regprocedure),'copy saves use caller RLS');
select ok(not (select prosecdef from pg_proc where oid='public.save_movie_diary(uuid,boolean,smallint)'::regprocedure),'diary saves use caller RLS');
select ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='public.create_collection_library(uuid,text)'::regprocedure),'atomic creation pins search path');
insert into auth.users(id,email) values('11000000-0000-0000-0000-000000000001','collection-sql@shogun.test');
set local role authenticated;
select set_config('request.jwt.claim.sub','11000000-0000-0000-0000-000000000001',true);
select is(jsonb_array_length(public.collection_snapshot()->'libraries'),1,'snapshot has bootstrapped library');
select is(jsonb_array_length(public.collection_snapshot()->'copies'),0,'brand-new library has no copies');
select lives_ok($$select public.create_collection_library('22000000-0000-0000-0000-000000000001','Shared')$$,'create shared library');
select lives_ok($$select public.create_collection_library('22000000-0000-0000-0000-000000000001','Shared')$$,'retry shared library');
select is((select count(*) from public.libraries),2::bigint,'retry did not duplicate library');
insert into public.movies(id,title) values('33000000-0000-0000-0000-000000000001','SQL collection film');
select lives_ok($$select public.save_collection_copy('44000000-0000-0000-0000-000000000001','22000000-0000-0000-0000-000000000001','33000000-0000-0000-0000-000000000001','DVD')$$,'save copy');
select lives_ok($$select public.save_collection_copy('44000000-0000-0000-0000-000000000001','22000000-0000-0000-0000-000000000001','33000000-0000-0000-0000-000000000001','DVD')$$,'retry copy');
select is((select count(*) from public.owned_copies),1::bigint,'copy retry did not duplicate');
select throws_ok($$select public.save_collection_copy('44000000-0000-0000-0000-000000000001','22000000-0000-0000-0000-000000000001','33000000-0000-0000-0000-000000000001','VHS')$$,'42501',null,'reusing identity with different payload rejected');
select lives_ok($$select public.save_movie_diary('33000000-0000-0000-0000-000000000001',true,5::smallint)$$,'save private diary');
select lives_ok($$select public.save_movie_diary('33000000-0000-0000-0000-000000000001',false,null)$$,'clear rating');
select is((select rating from public.personal_movie_state),null::smallint,'rating cleared durably');
select throws_ok($$select public.save_movie_diary('33000000-0000-0000-0000-000000000001',true,6::smallint)$$,'23514',null,'rating bounds enforced');
select lives_ok($$select public.set_default_library('22000000-0000-0000-0000-000000000001')$$,'save default');
select is(public.collection_snapshot()->>'default_library_id','22000000-0000-0000-0000-000000000001','snapshot returns saved default');
select * from finish();
rollback;
